<section v-else-if="route==='events'||route==='event-detail'||route==='event-register'" class="p-5 py-8"><template v-if="route==='events'"><p class="text-xs font-bold tracking-[.16em] text-wine">EVENTS</p><h1 class="serif mt-2 text-4xl text-navy">Find your next gathering</h1><p class="mt-3 text-sm leading-6 text-navy/65">Annual traditions, professional chapters, sport, service and easy social meet-ups.</p><div class="mt-5 flex gap-2 overflow-x-auto pb-2"><button v-for="category in eventCategories" :key="category" class="shrink-0 rounded-full px-3 py-2 text-xs font-bold" :class="eventCategory===category?'bg-gold text-black':'border border-navy/15 bg-white text-navy'" @click="eventCategory=category">{{category}}</button></div><div class="mt-4 space-y-4"><button v-for="event in eventsShown" :key="event.id" class="w-full overflow-hidden rounded-2xl border border-navy/10 bg-white text-left shadow-sm" @click="selectedEvent=event.id;go('event-detail')"><img :src="event.image" class="h-44 w-full object-cover" :alt="event.title"><span class="block p-4"><span class="flex items-center justify-between gap-3"><small class="font-bold uppercase tracking-wider text-wine">{{event.category}}</small><small class="rounded-full bg-gold/25 px-2 py-1 font-bold text-navy">{{event.status}}</small></span><strong class="serif mt-2 block text-2xl leading-tight text-navy">{{event.title}}</strong><small class="mt-2 block leading-5 text-navy/60">{{event.date}} · {{event.venue}}</small></span></button></div></template><template v-else-if="route==='event-detail'"><button class="mb-4 text-sm font-bold text-wine" @click="go('events')">← All events</button><img :src="activeEvent.image" class="h-56 w-full rounded-2xl object-cover" :alt="activeEvent.title"><p class="mt-5 text-xs font-bold uppercase tracking-[.16em] text-wine">{{activeEvent.category}} · {{activeEvent.status}}</p><h1 class="serif mt-2 text-4xl leading-tight text-navy">{{activeEvent.title}}</h1><p class="mt-3 text-sm font-bold text-navy">{{activeEvent.date}}<br>{{activeEvent.venue}}</p><p class="mt-4 leading-7 text-navy/70">{{activeEvent.description}}</p><div class="mt-5 rounded-2xl bg-white p-4"><b class="text-sm text-navy">What to expect</b><div v-for="item in activeEvent.highlights" :key="item" class="mt-3 flex gap-3 text-sm text-navy/70"><span class="text-wine">●</span>{{item}}</div></div><button class="mt-5 w-full rounded-xl bg-gold py-3 font-bold" @click="go('event-register')">Register interest</button></template><template v-else><p class="text-xs font-bold text-wine">{{activeEvent.category.toUpperCase()}}</p><h1 class="serif mt-2 text-4xl text-navy">{{registered?'Registration submitted':activeEvent.title}}</h1><div v-if="!registered"><div class="mt-6 rounded-2xl bg-white p-4"><b>{{activeEvent.date}}</b><small class="mt-1 block text-navy/60">{{activeEvent.venue}}</small></div><input class="mt-3 w-full rounded-xl border border-navy/20 bg-white p-3" placeholder="Attendee name"><input class="mt-3 w-full rounded-xl border border-navy/20 bg-white p-3" placeholder="Email address"><button class="mt-5 w-full rounded-xl bg-gold py-3 font-bold" @click="registered=true">Submit demo registration</button></div><div v-else class="mt-6 rounded-2xl bg-wine p-5 text-white"><b>We’ve received your registration.</b><p class="mt-2 text-sm text-white/70">A confirmation has been added to message history. Nothing has been charged.</p><button class="mt-5 rounded-lg bg-gold px-4 py-2 font-bold text-black" @click="go('portal-messages')">View message</button></div></template></section>

<section v-else-if="route==='membership'||route==='membership-types'||route==='membership-apply'"><div class="hero relative min-h-[250px] overflow-hidden p-5 pt-20 text-white"><img src="/assets/charity-service.jpeg" class="absolute inset-0 h-full w-full object-cover"><div class="relative z-10"><h1 class="serif text-4xl">Belong for life.</h1></div></div><div class="p-5"><template v-if="route==='membership'"><button class="w-full rounded-xl bg-gold py-3 font-bold" @click="go('membership-types')">Explore membership types</button><button class="mt-3 w-full rounded-xl border border-navy/20 bg-white py-3 font-bold" @click="go('membership-apply')">Start an application</button></template><template v-else-if="route==='membership-types'"><h2 class="serif text-3xl text-navy">Membership types</h2><div v-for="x in ['Youth · under 18','Trial · ages 18–27','Life · from age 28']" :key="x" class="mt-3 rounded-xl bg-white p-4">{{x}}</div><button class="mt-5 w-full rounded-xl bg-gold py-3 font-bold" @click="go('membership-apply')">Apply now</button></template><template v-else><h2 class="serif text-3xl text-navy">Start your application</h2><input v-for="x in ['Full name','Email address','Mobile number','Class of year']" :key="x" class="mt-3 w-full rounded-xl border border-navy/20 p-3" :placeholder="x"><button class="mt-5 w-full rounded-xl bg-gold py-3 font-bold" @click="say('Application submitted for GenCom review')">Submit application</button></template></div></section>

<section v-else-if="contentPages[route]" class="p-5 py-8"><p class="text-xs font-bold tracking-[.16em] text-wine">{{contentPages[route].eyebrow.toUpperCase()}}</p><h1 class="serif mt-3 text-4xl leading-tight text-navy">{{contentPages[route].title}}</h1><p class="mt-4 text-[15px] leading-7 text-navy/70">{{contentPages[route].intro}}</p><div class="mt-6 overflow-hidden rounded-2xl border border-navy/10 bg-white"><button v-for="item in contentPages[route].items" :key="item" class="flex w-full items-center justify-between border-b border-navy/10 p-4 text-left text-sm font-bold text-navy" @click="say(item+' opened')">{{item}} <span class="text-wine">›</span></button></div><button v-if="contentPages[route].cta" class="mt-5 w-full rounded-xl bg-gold py-3 font-bold" @click="go(contentPages[route].cta![1])">{{contentPages[route].cta![0]}}</button></section>
<section v-else-if="route==='login'||route==='claim'" class="p-5 py-10"><p class="text-xs font-bold text-wine">MEMBER ACCESS</p><h1 class="serif mt-3 text-4xl text-navy">{{route==='login'?'Welcome back.':'Claim your account.'}}</h1><div v-if="route==='login'" class="mt-7 space-y-3"><button class="w-full rounded-xl bg-navy p-4 text-left text-white" @click="login('life')"><b>Edward Lau · Life member</b><small class="block text-white/60">Active member experience</small></button><button class="w-full rounded-xl bg-white p-4 text-left" @click="login('trial')"><b>Brian Lee · Trial member</b></button><button class="w-full rounded-xl bg-wine p-4 text-left text-white" @click="login('suspended')"><b>Alex Chan · Suspended member</b><small class="block text-white/60">Payment recovery experience</small></button><button class="font-bold text-wine underline" @click="go('claim')">Claim legacy account</button></div><div v-else class="mt-6"><input class="w-full rounded-xl border p-3" placeholder="Email"><input class="mt-3 w-full rounded-xl border p-3" placeholder="One-time access code"><button class="mt-5 w-full rounded-xl bg-gold py-3 font-bold" @click="say('Claim link sent—demo only')">Claim account</button></div></section>

<section v-else-if="route==='portal-suspended'" class="p-5 py-9"><p class="text-xs font-bold text-wine">ACCOUNT RESTRICTED</p><h1 class="serif mt-3 text-4xl text-navy">Let’s restore your membership.</h1><div class="mt-6 rounded-2xl bg-wine p-5 text-white"><b>Life membership payment is overdue.</b><p class="mt-2 text-sm text-white/70">Directory and member event access are paused.</p></div><button class="mt-5 w-full rounded-xl bg-gold py-3 font-bold" @click="go('portal-membership')">Review payment reminder</button></section>
<section v-else-if="route==='portal-home'" class="p-5 py-8"><p class="text-xs font-bold text-wine">MEMBER HOME</p><h1 class="serif mt-2 text-4xl text-navy">Hi, {{member==='trial'?'Brian':'Edward'}}.</h1><div class="mt-5 rounded-2xl bg-navy p-5 text-white"><b class="text-gold">{{member==='trial'?'TRIAL':'ACTIVE'}}</b><h2 class="serif text-3xl">{{member==='trial'?'Trial member':'Life member'}}</h2></div><div class="mt-4 grid grid-cols-2 gap-3"><button class="rounded-xl bg-white p-4 text-left" @click="go('portal-directory')"><b class="block text-2xl text-wine">248</b><small>Directory members</small></button><button class="rounded-xl bg-white p-4 text-left" @click="go('event-detail')"><b class="block text-2xl text-wine">1</b><small>Featured event</small></button></div></section>
<section v-else-if="route==='portal-profile'" class="p-5 py-8"><h1 class="serif text-4xl text-navy">My profile</h1><div class="mt-5 flex items-center gap-4"><b class="grid h-16 w-16 place-items-center rounded-full bg-gold">EL</b><span>Edward Lau<small class="block">Class of 2007</small></span></div><input v-for="x in ['Email','Mobile','Industry','Company']" :key="x" class="mt-3 w-full rounded-xl border p-3" :placeholder="x"><button class="mt-5 w-full rounded-xl bg-gold py-3 font-bold" @click="say('Profile saved')">Save profile</button></section>
<section v-else-if="route==='portal-directory'" class="p-5 py-8"><h1 class="serif text-4xl text-navy">Alumni directory</h1><div class="mt-5 flex gap-2 overflow-auto"><button v-for="x in ['All','Finance','Legal','Technology','Design','Medical']" :key="x" class="shrink-0 rounded-full px-3 py-2 text-xs font-bold" :class="filter===x?'bg-gold':'bg-white'" @click="filter=x">{{x}}</button></div><button v-for="p in shown" :key="p[0]" class="mt-3 flex w-full justify-between rounded-xl bg-white p-4 text-left" @click="say(p[0]+' profile opened')"><span><b>{{p[0]}}</b><small class="block">{{p[1]}} · {{p[2]}}</small></span><span>›</span></button></section>
<section v-else-if="route==='portal-membership'" class="p-5 py-8"><h1 class="serif text-4xl text-navy">{{member==='suspended'?'Payment recovery':'Your membership'}}</h1><div class="mt-6 rounded-xl bg-white p-5"><b>{{member==='suspended'?'Life payment overdue':'Membership active'}}</b><p class="mt-2 text-sm">{{member==='suspended'?'Access returns immediately after demo payment.':'Your record is up to date.'}}</p></div><button v-if="member==='suspended'" class="mt-5 w-full rounded-xl bg-gold py-3 font-bold" @click="member='life';go('portal-home');say('Membership restored')">Complete demo payment</button></section>
<section v-else class="p-5 py-8"><h1 class="serif text-4xl text-navy">Message history</h1><article v-for="x in ['Annual Dinner registration received','Profile updated','Life membership reminder']" :key="x" class="mt-4 rounded-xl bg-white p-4"><small class="font-bold text-wine">EMAIL + WHATSAPP</small><b class="block">{{x}}</b></article></section>
<footer v-if="!portal" class="bg-[#07131f] px-5 py-8 text-white"><div class="flex items-center gap-3"><img src="/assets/logo.png" class="h-14 w-12 object-contain"><div><b class="serif text-2xl">DSOBA</b><small class="block text-white/50">Dalton School Old Boys’ Association</small></div></div><p class="mt-5 text-sm leading-6 text-white/60">Connecting alumni across generations, professions and places.</p><div class="mt-7 grid grid-cols-2 gap-x-5"><div><b class="text-xs tracking-wider text-gold">EXPLORE</b><button v-for="x in [['Home','home'],['About DSOBA','about'],['Mission','about'],['Committees','about'],['Chapters & Groups','chapters']]" :key="x[0]" class="block py-2 text-left text-sm text-white/75" @click="go(x[1])">{{x[0]}}</button></div><div><b class="text-xs tracking-wider text-gold">DISCOVER</b><button v-for="x in [['DSOBA News','news'],['Upcoming Events','events'],['Past Events','events'],['Annual Dinner','event-detail'],['Membership','membership']]" :key="x[0]" class="block py-2 text-left text-sm text-white/75" @click="go(x[1])">{{x[0]}}</button></div><div class="mt-5"><b class="text-xs tracking-wider text-gold">MEMBERSHIP</b><button v-for="x in [['Why Join','membership'],['Life / Trial / Youth','membership-types'],['Apply Now','membership-apply'],['Enquiry','membership'],['DSOBA Credit Card','membership']]" :key="x[0]" class="block py-2 text-left text-sm text-white/75" @click="go(x[1])">{{x[0]}}</button></div><div class="mt-5"><b class="text-xs tracking-wider text-gold">MEMBER SERVICES</b><button class="block py-2 text-left text-sm text-white/75" @click="go('login')">Member login</button><button class="block py-2 text-left text-sm text-white/75" @click="go('claim')">Claim account</button><button class="block py-2 text-left text-sm text-white/75" @click="go('portal-directory')">Alumni directory</button><button class="block py-2 text-left text-sm text-white/75" @click="say('WhatsApp contact preview')">Contact / WhatsApp</button></div></div><div class="mt-7 border-t border-white/10 pt-5"><div class="flex flex-wrap gap-x-4 gap-y-2 text-xs text-white/45"><button @click="say('Useful links preview')">Useful Links</button><button @click="say('Privacy policy preview')">Privacy Policy</button><button @click="say('Terms preview')">Terms & Conditions</button><button @click="say('Personal data preview')">Personal Data</button></div><p class="mt-5 text-[11px] text-white/35">© 2026 DSOBA · Mobile stakeholder demo</p></div></footer><div v-if="toast" class="fixed bottom-5 left-1/2 z-40 w-[calc(100%-3rem)] max-w-[380px] -translate-x-1/2 rounded-xl bg-navy p-3 text-center text-sm font-bold text-white">{{toast}}</div></main></template>











